"""Minimum Cost to Merge Stones — interval DP with a "piles left" dimension.

dp[i][j][p] is the cheapest way to reduce stones[i..j] to p piles. Merging is
only possible when (n - 1) % (k - 1) == 0.

Time: O(n^3 * k)   Space: O(n^2 * k)
"""
from functools import lru_cache
from itertools import accumulate
from typing import List


class Solution:
    def mergeStones(self, stones: List[int], k: int) -> int:
        n = len(stones)
        if (n - 1) % (k - 1):
            return -1
        prefix = [0] + list(accumulate(stones))

        @lru_cache(maxsize=None)
        def solve(i: int, j: int, piles: int) -> int:
            if i == j:
                return 0 if piles == 1 else float("inf")
            if piles == 1:
                merged = solve(i, j, k)
                return merged + prefix[j + 1] - prefix[i] if merged < float("inf") else merged
            best = float("inf")
            for mid in range(i, j, k - 1):
                best = min(best, solve(i, mid, 1) + solve(mid + 1, j, piles - 1))
            return best

        answer = solve(0, n - 1, 1)
        return -1 if answer == float("inf") else answer
